import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const ROASTS = [
  "Teacher forgot your face",
  "Security thinks you’re a visitor",
  "Even WiFi attends more than you",
  "Bring parents tomorrow",
  "Attendance found in museum records",
  "You attend only on result day?",
  "HOD asks 'Who is this?'",
  "Your seat has been sold to a junior"
];

const LOADING_MSGS = [
  "Verifying with university server...",
  "Contacting HOD...",
  "Checking CCTV footage...",
  "Calculating bunk velocity...",
  "Analyzing excuses database..."
];

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result'>('form');
  const [name, setName] = useState('');
  const [total, setTotal] = useState('');
  const [attended, setAttended] = useState('');
  const [loadingIndex, setLoadingIndex] = useState(0);
  const [isEligible, setIsEligible] = useState(false);
  const [roast, setRoast] = useState('');
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [medicalStatus, setMedicalStatus] = useState<'idle' | 'checking' | 'rejected'>('idle');
  const [medicalRejectReason, setMedicalRejectReason] = useState('');

  // Reset state when opening
  useEffect(() => {
    if (isOpen) {
      setStep('form');
      setMedicalStatus('idle');
      setShowFakeCall(false);
      setName('');
      setTotal('');
      setAttended('');
    }
  }, [isOpen]);

  // Loading sequence
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setLoadingIndex(prev => (prev + 1) % LOADING_MSGS.length);
      }, 800);

      const timeout = setTimeout(() => {
        clearInterval(interval);
        const t = parseInt(total) || 0;
        const a = parseInt(attended) || 0;
        const pct = t === 0 ? 0 : (a / t) * 100;

        setIsEligible(pct >= 75);
        if (pct < 75) {
            setRoast(ROASTS[Math.floor(Math.random() * ROASTS.length)]);
            // Schedule fake call
            setTimeout(() => setShowFakeCall(true), 3000);
        }
        setStep('result');
      }, 3500);

      return () => {
        clearInterval(interval);
        clearTimeout(timeout);
      }
    }
  }, [step, total, attended]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!total || !attended) return;
    setStep('loading');
  };

  const handleMedicalCertificate = () => {
    setMedicalStatus('checking');
    setTimeout(() => {
        const reasons = ["Ink too fresh", "Doctor is your uncle", "HOD denied instantly", "Certificate used by 5 others"];
        setMedicalRejectReason(reasons[Math.floor(Math.random() * reasons.length)]);
        setMedicalStatus('rejected');
    }, 1500);
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
       <motion.div 
         initial={{ opacity: 0 }} 
         animate={{ opacity: 1 }} 
         exit={{ opacity: 0 }}
         className="fixed inset-0 z-[100000] bg-black/90 flex items-center justify-center p-4 font-sans"
       >
         {/* Close button for safety */}
         <button onClick={onClose} className="absolute top-4 right-4 text-white/50 hover:text-white z-50">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
         </button>

         {step === 'form' && (
            <motion.div 
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden relative z-50"
            >
                <div className="bg-blue-800 p-6 text-center border-b-4 border-yellow-500">
                    <h2 className="text-2xl font-bold text-white uppercase tracking-wider">University Portal</h2>
                    <p className="text-blue-200 text-xs mt-1">Examination Eligibility Check v2.4</p>
                </div>
                <form onSubmit={handleSubmit} className="p-8 space-y-6">
                    <div>
                        <label className="block text-gray-700 text-sm font-bold mb-2">Student Name</label>
                        <input 
                            required
                            type="text" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black"
                            placeholder="Enter full name"
                            value={name}
                            onChange={e => setName(e.target.value)}
                        />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-gray-700 text-sm font-bold mb-2">Total Classes</label>
                            <input 
                                required
                                type="number" 
                                className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black"
                                placeholder="0"
                                value={total}
                                onChange={e => setTotal(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-gray-700 text-sm font-bold mb-2">Attended</label>
                            <input 
                                required
                                type="number" 
                                className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black"
                                placeholder="0"
                                value={attended}
                                onChange={e => setAttended(e.target.value)}
                            />
                        </div>
                    </div>
                    <button 
                        type="submit"
                        className="w-full bg-blue-700 hover:bg-blue-800 text-white font-bold py-4 rounded shadow-lg transform transition active:scale-95 flex justify-center items-center gap-2"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                        </svg>
                        CHECK ELIGIBILITY
                    </button>
                    <div className="text-center">
                        <p className="text-xs text-gray-400">Secure Server Connection • SSL Encrypted</p>
                    </div>
                </form>
            </motion.div>
         )}

         {step === 'loading' && (
            <div className="text-center text-white space-y-8 z-50">
                <div className="w-20 h-20 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <div className="space-y-2">
                    <h3 className="text-2xl font-bold font-mono">PROCESSING...</h3>
                    <motion.p 
                        key={loadingIndex}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="text-blue-300 font-mono"
                    >
                        {LOADING_MSGS[loadingIndex]}
                    </motion.p>
                </div>
            </div>
         )}

         {step === 'result' && isEligible && (
            <motion.div 
                initial={{ scale: 0.5, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-green-600 text-white p-10 rounded-3xl text-center shadow-[0_0_100px_rgba(34,197,94,0.6)] relative overflow-hidden max-w-2xl w-full z-50"
            >
                {/* Confetti (Simple CSS dots) */}
                {[...Array(20)].map((_, i) => (
                    <motion.div
                        key={i}
                        className="absolute w-3 h-3 bg-white rounded-full"
                        initial={{ 
                            x: Math.random() * 600 - 300, 
                            y: -200, 
                            opacity: 1 
                        }}
                        animate={{ 
                            y: 800, 
                            rotate: 360,
                            opacity: 0
                        }}
                        transition={{ 
                            duration: Math.random() * 2 + 2, 
                            repeat: Infinity, 
                            delay: Math.random() * 2 
                        }}
                        style={{ left: '50%' }}
                    />
                ))}

                <div className="relative z-10">
                    <div className="text-6xl mb-6">🎉</div>
                    <h2 className="text-5xl font-black mb-4 uppercase tracking-tighter">Eligible!</h2>
                    <p className="text-xl font-medium text-green-100 mb-8">Congratulations, responsible human.</p>
                    <div className="bg-white/20 p-4 rounded-xl inline-block">
                        <p className="font-mono text-sm">HALL TICKET GENERATED</p>
                    </div>
                </div>
            </motion.div>
         )}

         {step === 'result' && !isEligible && (
            <div className="w-full h-full flex items-center justify-center relative overflow-hidden">
                {/* Flashing Red Background */}
                <motion.div 
                    animate={{ opacity: [0, 0.5, 0] }}
                    transition={{ duration: 0.5, repeat: Infinity }}
                    className="absolute inset-0 bg-red-600 z-0 pointer-events-none"
                />

                <motion.div 
                    className="relative z-10 bg-black border-4 border-red-600 p-8 md:p-12 rounded-lg max-w-2xl w-full text-center shadow-2xl"
                    initial={{ scale: 0.9 }}
                    animate={{ scale: [1, 1.02, 1] }}
                    transition={{ repeat: Infinity, duration: 0.2 }}
                >
                    <h1 className="text-5xl md:text-7xl font-black text-red-600 mb-6 tracking-tighter" style={{ textShadow: '0 0 10px red' }}>
                        NOT ELIGIBLE
                    </h1>

                    <p className="text-2xl text-white font-bold mb-8 uppercase font-mono leading-tight">
                        {roast}
                    </p>

                    <div className="space-y-4">
                        <button 
                            onClick={handleMedicalCertificate}
                            disabled={medicalStatus !== 'idle'}
                            className="bg-yellow-600 hover:bg-yellow-500 text-black font-bold py-3 px-8 rounded uppercase tracking-wider text-sm md:text-base w-full md:w-auto transition-all"
                        >
                            {medicalStatus === 'idle' && "Try with Medical Certificate"}
                            {medicalStatus === 'checking' && "Verifying Certificate..."}
                            {medicalStatus === 'rejected' && "REJECTED"}
                        </button>

                        {medicalStatus === 'rejected' && (
                            <motion.p 
                                initial={{ opacity: 0, x: -10 }}
                                animate={{ opacity: 1, x: 0, x: [0, -5, 5, 0] }}
                                className="text-red-500 font-mono font-bold"
                            >
                                ❌ REASON: {medicalRejectReason}
                            </motion.p>
                        )}
                    </div>
                </motion.div>

                {/* Fake Call Overlay */}
                <AnimatePresence>
                    {showFakeCall && (
                        <motion.div
                            initial={{ y: '100%' }}
                            animate={{ y: 0 }}
                            exit={{ y: '100%' }}
                            className="absolute bottom-0 left-0 right-0 bg-gray-900 border-t border-gray-700 p-6 z-50 flex items-center justify-between"
                        >
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 bg-gray-700 rounded-full flex items-center justify-center text-2xl animate-pulse">
                                    📞
                                </div>
                                <div>
                                    <h4 className="text-white font-bold text-lg">HOD Calling...</h4>
                                    <p className="text-gray-400 text-sm">Mobile</p>
                                </div>
                            </div>
                            <div className="flex gap-4">
                                <button onClick={() => setShowFakeCall(false)} className="w-12 h-12 rounded-full bg-red-500 flex items-center justify-center">
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
