const ROASTS = [
  "Teacher forgot your face",
  "Security thinks you’re a visitor",
  "Even WiFi attends more than you",
  "Bring parents tomorrow",
  "Attendance found in museum records",
  "You attend only on result day?",
  "HOD asks 'Who is this?'",
  "Your seat has been sold to a junior"
];

const LOADING_MSGS = [
  "Verifying with university server...",
  "Contacting HOD...",
  "Checking CCTV footage...",
  "Calculating bunk velocity...",
  "Analyzing excuses database..."
];

