  const [isEligible, setIsEligible] = useState(false);
  const [roast, setRoast] = useState('');
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [medicalStatus, setMedicalStatus] = useState<'idle' | 'checking' | 'rejected'>('idle');
  const [medicalRejectReason, setMedicalRejectReason] = useState('');

  // Reset state when opening
  useEffect(() => {
    if (isOpen) {
      setStep('form');
      setMedicalStatus('idle');
      setShowFakeCall(false);
      setName('');
      setTotal('');
      setAttended('');
    }
  }, [isOpen]);

  // Loading sequence
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setLoadingIndex(prev => (prev + 1) % LOADING_MSGS.length);
      }, 800);

      const timeout = setTimeout(() => {
        clearInterval(interval);
        const t = parseInt(total) || 0;
        const a = parseInt(attended) || 0;
        const pct = t === 0 ? 0 : (a / t) * 100;

        setIsEligible(pct >= 75);
        if (pct < 75) {
            setRoast(ROASTS[Math.floor(Math.random() * ROASTS.length)]);
            // Schedule fake call
            setTimeout(() => setShowFakeCall(true), 3000);
        }
        setStep('result');
      }, 3500);

      return () => {
        clearInterval(interval);
        clearTimeout(timeout);
      }
    }
  }, [step, total, attended]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!total || !attended) return;
    setStep('loading');
  };

  const handleMedicalCertificate = () => {
    setMedicalStatus('checking');
    setTimeout(() => {
        const reasons = ["Ink too fresh", "Doctor is your uncle", "HOD denied instantly", "Certificate used by 5 others"];
        setMedicalRejectReason(reasons[Math.floor(Math.random() * reasons.length)]);
        setMedicalStatus('rejected');
