  if (!isOpen) return null;

  return (
    <AnimatePresence>
       <motion.div 
         initial={{ opacity: 0 }} 
         animate={{ opacity: 1 }} 
         exit={{ opacity: 0 }}
         className="fixed inset-0 z-[100000] bg-black/90 flex items-center justify-center p-4 font-sans"
       >
