                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
         </button>

         {step === 'form' && (
            <motion.div 
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden relative z-50"
            >
                <div className="bg-blue-800 p-6 text-center border-b-4 border-yellow-500">
