                <div className="relative z-10">
                    <div className="text-6xl mb-6 bounce">🎉</div>
                    <h2 className="text-5xl font-black mb-2 uppercase tracking-tighter">Eligible!</h2>
                    <div className="text-3xl font-bold mb-6 text-green-200">{percentage.toFixed(1)}%</div>
                    <p className="text-xl font-medium text-green-100 mb-8">Congratulations, responsible human.</p>
                    <div className="bg-white/20 border border-white/30 p-4 rounded-xl inline-block backdrop-blur-sm">
                        <p className="font-mono text-sm font-bold tracking-widest">HALL TICKET GENERATED</p>
                        <p className="text-xs opacity-75 mt-1">ID: {Math.random().toString(36).substr(2, 9).toUpperCase()}</p>
                    </div>
                </div>
            </motion.div>
         )}

         {step === 'result' && !isEligible && (
            <div className="w-full h-full flex items-center justify-center relative overflow-hidden">
                {/* Siren Effect Background */}
                <motion.div 
                    animate={{ backgroundColor: ["#991b1b", "#1e3a8a", "#991b1b"] }}
                    transition={{ duration: 0.5, repeat: Infinity }}
                    className="absolute inset-0 z-0 pointer-events-none opacity-50"
                />

                <motion.div 
                    className="relative z-10 bg-black border-4 border-red-600 p-8 md:p-12 rounded-lg max-w-2xl w-full text-center shadow-[0_0_50px_rgba(220,38,38,0.5)]"
                    initial={{ scale: 0.9 }}
                    animate={{ scale: [1, 1.02, 1] }}
                    transition={{ repeat: Infinity, duration: 0.2 }}
                >
                    <div className="mb-4">
                         <span className="text-6xl">🚨</span>
                    </div>
                    <h1 className="text-4xl md:text-6xl font-black text-red-500 mb-2 tracking-tighter" style={{ textShadow: '0 0 10px red' }}>
                        NOT ELIGIBLE
                    </h1>
                    <div className="text-3xl font-bold mb-6 text-red-200 font-mono">{percentage.toFixed(1)}%</div>

                    <p className="text-xl md:text-2xl text-white font-bold mb-8 uppercase font-mono leading-tight bg-red-900/30 p-4 rounded border border-red-500/30">
                        {roast}
                    </p>

                    <div className="space-y-4">
                        <button 
                            onClick={handleMedicalCertificate}
                            disabled={medicalStatus !== 'idle'}
                            className="bg-yellow-600 hover:bg-yellow-500 text-black font-bold py-4 px-8 rounded uppercase tracking-wider text-sm md:text-base w-full md:w-auto transition-all shadow-lg hover:shadow-yellow-500/50"
                        >
                            {medicalStatus === 'idle' && "Try with Medical Certificate"}
                            {medicalStatus === 'checking' && "Verifying Certificate..."}
                            {medicalStatus === 'rejected' && "❌ REJECTED"}
                        </button>

                        {medicalStatus === 'rejected' && (
                            <motion.div 
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                className="bg-red-900/50 p-2 rounded border border-red-500 text-red-200 font-mono text-sm"
                            >
                                SYSTEM REASON: {medicalRejectReason}
                            </motion.div>
                        )}
