                            )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
         )}
       </motion.div>
    </AnimatePresence>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const ROASTS = [
  "Teacher forgot your face",
  "Security thinks you’re a visitor",
  "Even WiFi attends more than you",
  "Bring parents tomorrow",
  "Attendance found in museum records",
  "You attend only on result day?",
  "HOD asks 'Who is this?'",
  "Your seat has been sold to a junior"
];

const LOADING_MSGS = [
  "Verifying with university server...",
  "Contacting HOD...",
  "Checking CCTV footage...",
  "Calculating bunk velocity...",
  "Analyzing excuses database..."
];

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result'>('form');
  const [name, setName] = useState('');
  const [total, setTotal] = useState('');
  const [attended, setAttended] = useState('');
  const [examDate, setExamDate] = useState('');
  const [holidays, setHolidays] = useState(''); 
  const [loadingIndex, setLoadingIndex] = useState(0);
  const [isEligible, setIsEligible] = useState(false);
  const [percentage, setPercentage] = useState(0);
  const [roast, setRoast] = useState('');
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [callStatus, setCallStatus] = useState<'incoming' | 'connected'>('incoming');
  const [medicalStatus, setMedicalStatus] = useState<'idle' | 'checking' | 'rejected'>('idle');
  const [medicalRejectReason, setMedicalRejectReason] = useState('');

  // Audio Refs
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeOscillatorsRef = useRef<OscillatorNode[]>([]);
  const ringtoneIntervalRef = useRef<number | null>(null);

  // Initialize Audio Context safely
  const initAudio = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContextClass) {
          audioCtxRef.current = new AudioContextClass();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAllSounds = () => {
    // Stop all tracked oscillators
    activeOscillatorsRef.current.forEach(osc => {
        try {
            osc.stop();
            osc.disconnect();
        } catch(e) {}
    });
    activeOscillatorsRef.current = [];

    // Clear ringtone interval
    if (ringtoneIntervalRef.current) {
        clearInterval(ringtoneIntervalRef.current);
        ringtoneIntervalRef.current = null;
    }
  };

  const playSiren = () => {
     stopAllSounds();
     initAudio();
     const ctx = audioCtxRef.current;
     if(!ctx) return;

     const osc = ctx.createOscillator();
     const gain = ctx.createGain();

     osc.type = 'sawtooth';
     osc.frequency.setValueAtTime(600, ctx.currentTime);
     gain.gain.value = 0.1;

     // LFO for modulation (the wee-woo effect)
     const lfo = ctx.createOscillator();
     lfo.type = 'triangle';
     lfo.frequency.value = 2; // Hz
     const lfoGain = ctx.createGain();
     lfoGain.gain.value = 200;

     lfo.connect(lfoGain);
     lfoGain.connect(osc.frequency);

     osc.connect(gain);
     gain.connect(ctx.destination);

     osc.start();
     lfo.start();

     activeOscillatorsRef.current.push(osc);
     activeOscillatorsRef.current.push(lfo);
  };

  const playSuccess = () => {
     stopAllSounds();
     initAudio();
     const ctx = audioCtxRef.current;
     if(!ctx) return;

     const playNote = (freq: number, time: number, duration: number) => {
         const osc = ctx.createOscillator();
         const gain = ctx.createGain();
         osc.type = 'sine';
         osc.frequency.value = freq;

         gain.gain.setValueAtTime(0.05, time);
         gain.gain.exponentialRampToValueAtTime(0.001, time + duration);

         osc.connect(gain);
         gain.connect(ctx.destination);
         osc.start(time);
         osc.stop(time + duration);

         // No need to track these short notes for stopping usually, but good practice
         setTimeout(() => {
            try { osc.disconnect(); gain.disconnect(); } catch(e){}
         }, duration * 1000 + 100);
     };

     const now = ctx.currentTime;
     playNote(523.25, now, 0.5); // C5
     playNote(659.25, now + 0.1, 0.5); // E5
     playNote(783.99, now + 0.2, 0.8); // G5
     playNote(1046.50, now + 0.3, 1.5); // C6
  };

  const playRingtone = () => {
     stopAllSounds(); // Stop siren if playing
     initAudio();
     const ctx = audioCtxRef.current;
     if(!ctx) return;

     const playRing = () => {
         const now = ctx.currentTime;
         const osc1 = ctx.createOscillator();
         const osc2 = ctx.createOscillator();
         const gain = ctx.createGain();

         osc1.type = 'square';
         osc1.frequency.value = 800;
         osc2.type = 'square';
         osc2.frequency.value = 1000;

         gain.gain.setValueAtTime(0.05, now);
         gain.gain.linearRampToValueAtTime(0, now + 1.0);

         osc1.connect(gain);
         osc2.connect(gain);
         gain.connect(ctx.destination);

         osc1.start(now);
         osc1.stop(now + 1.0);
         osc2.start(now + 0.1); // slight offset
         osc2.stop(now + 1.0);

         activeOscillatorsRef.current.push(osc1, osc2);
     };

     playRing();
     ringtoneIntervalRef.current = window.setInterval(playRing, 2000);
  };

  const playErrorBuzz = () => {
      initAudio();
      const ctx = audioCtxRef.current;
      if(!ctx) return;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      osc.frequency.linearRampToValueAtTime(50, ctx.currentTime + 0.4);

      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.4);
  };

  // Reset state when opening
  useEffect(() => {
    if (isOpen) {
      setStep('form');
      setMedicalStatus('idle');
      setShowFakeCall(false);
      setCallStatus('incoming');
      setName('');
      setTotal('');
      setAttended('');
      setExamDate('');
      setHolidays('');
      stopAllSounds();
    } else {
        stopAllSounds();
    }

    return () => stopAllSounds();
  }, [isOpen]);

  // Loading sequence
  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setLoadingIndex(prev => (prev + 1) % LOADING_MSGS.length);
      }, 800);

      const timeout = setTimeout(() => {
        clearInterval(interval);
        const t = parseInt(total) || 0;
        const a = parseInt(attended) || 0;
        const pct = t === 0 ? 0 : (a / t) * 100;
        setPercentage(pct);

        const eligible = pct >= 75;
        setIsEligible(eligible);

        if (eligible) {
            playSuccess();
        } else {
            playSiren();
            setRoast(ROASTS[Math.floor(Math.random() * ROASTS.length)]);
            // Schedule fake call
            setTimeout(() => {
                setShowFakeCall(true);
                playRingtone();
            }, 3000);
        }
        setStep('result');
      }, 3500);

      return () => {
        clearInterval(interval);
        clearTimeout(timeout);
      }
    }
  }, [step, total, attended]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    initAudio(); // Initialize audio on user interaction
    if (!total || !attended) return;
    setStep('loading');
  };

  const handleMedicalCertificate = () => {
    initAudio();
    setMedicalStatus('checking');
    setTimeout(() => {
        const reasons = ["Ink too fresh", "Doctor is your uncle", "HOD denied instantly", "Certificate used by 5 others"];
        setMedicalRejectReason(reasons[Math.floor(Math.random() * reasons.length)]);
        setMedicalStatus('rejected');
        playErrorBuzz();
    }, 1500);
  };

  const answerCall = () => {
    initAudio();
    setCallStatus('connected');
    stopAllSounds(); // Stop ringtone
    setTimeout(() => {
        setShowFakeCall(false);
        setCallStatus('incoming');
        // Resume siren if we want to keep trolling, but silence is often funnier here after "Meet me after class"
        // playSiren(); 
    }, 4000);
  };

  const handleClose = () => {
    stopAllSounds();
    onClose();
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
       <motion.div 
         initial={{ opacity: 0 }} 
         animate={{ opacity: 1 }} 
         exit={{ opacity: 0 }}
         className="fixed inset-0 z-[100000] bg-black/90 flex items-center justify-center p-4 font-sans"
       >
         {/* Close button for safety */}
         <button onClick={handleClose} className="absolute top-4 right-4 text-white/50 hover:text-white z-50">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
         </button>

         {step === 'form' && (
            <motion.div 
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden relative z-50"
            >
                <div className="bg-blue-900 p-6 text-center border-b-4 border-yellow-500">
                    <h2 className="text-2xl font-bold text-white uppercase tracking-wider">University Portal</h2>
                    <p className="text-blue-200 text-xs mt-1">Examination Eligibility Check v2.4</p>
                </div>
                <form onSubmit={handleSubmit} className="p-8 space-y-4">
                    <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Student Name</label>
                        <input 
                            required
                            type="text" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                            placeholder="Enter full name"
                            value={name}
                            onChange={e => setName(e.target.value)}
                        />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Total Classes</label>
                            <input 
                                required
                                type="number" 
                                className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                                placeholder="0"
                                value={total}
                                onChange={e => setTotal(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Attended</label>
                            <input 
                                required
                                type="number" 
                                className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                                placeholder="0"
                                value={attended}
                                onChange={e => setAttended(e.target.value)}
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Exam Start Date</label>
                        <input 
                            type="date" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                            value={examDate}
                            onChange={e => setExamDate(e.target.value)}
                        />
                    </div>
                     <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Holidays (Optional)</label>
                        <input 
                            type="text" 
                            className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors"
                            placeholder="e.g. Diwali, Christmas"
                            value={holidays}
                            onChange={e => setHolidays(e.target.value)}
                        />
                    </div>

                    <button 
                        type="submit"
                        className="w-full bg-blue-800 hover:bg-blue-900 text-white font-bold py-4 rounded shadow-lg transform transition active:scale-95 flex justify-center items-center gap-2 mt-4"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        CHECK ELIGIBILITY
                    </button>
                    <div className="text-center">
                        <p className="text-[10px] text-gray-400 uppercase">Secure Server Connection • SSL Encrypted • Official Use Only</p>
                    </div>
                </form>
            </motion.div>
         )}

         {step === 'loading' && (
            <div className="text-center text-white space-y-8 z-50">
                <div className="relative">
                    <div className="w-24 h-24 border-4 border-blue-500/30 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-2xl">🔒</span>
                    </div>
                </div>
                <div className="space-y-2">
                    <h3 className="text-2xl font-bold font-mono tracking-widest">PROCESSING...</h3>
                    <motion.p 
                        key={loadingIndex}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="text-blue-300 font-mono text-sm"
                    >
                        {LOADING_MSGS[loadingIndex]}
                    </motion.p>
                </div>
            </div>
         )}

         {step === 'result' && isEligible && (
            <motion.div 
                initial={{ scale: 0.5, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-green-600 text-white p-10 rounded-3xl text-center shadow-[0_0_100px_rgba(34,197,94,0.6)] relative overflow-hidden max-w-2xl w-full z-50"
            >
                {/* Confetti */}
                {[...Array(30)].map((_, i) => (
                    <motion.div
                        key={i}
                        className="absolute w-2 h-2 bg-white rounded-full"
                        initial={{ 
                            x: Math.random() * 600 - 300, 
                            y: -200, 
                            opacity: 1 
                        }}
                        animate={{ 
                            y: 800, 
                            rotate: 360,
                            opacity: 0
                        }}
                        transition={{ 
                            duration: Math.random() * 2 + 2, 
                            repeat: Infinity, 
                            delay: Math.random() * 2 
                        }}
                        style={{ left: '50%' }}
                    />
                ))}

                <div className="relative z-10">
                    <div className="text-6xl mb-6 bounce">🎉</div>
                    <h2 className="text-5xl font-black mb-2 uppercase tracking-tighter">Eligible!</h2>
                    <div className="text-3xl font-bold mb-6 text-green-200">{percentage.toFixed(1)}%</div>
                    <p className="text-xl font-medium text-green-100 mb-8">Congratulations, responsible human.</p>
                    <div className="bg-white/20 border border-white/30 p-4 rounded-xl inline-block backdrop-blur-sm">
                        <p className="font-mono text-sm font-bold tracking-widest">HALL TICKET GENERATED</p>
                        <p className="text-xs opacity-75 mt-1">ID: {Math.random().toString(36).substr(2, 9).toUpperCase()}</p>
                    </div>
                </div>
            </motion.div>
         )}

         {step === 'result' && !isEligible && (
            <div className="w-full h-full flex items-center justify-center relative overflow-hidden">
                {/* Siren Effect Background */}
                <motion.div 
                    animate={{ backgroundColor: ["#991b1b", "#1e3a8a", "#991b1b"] }}
                    transition={{ duration: 0.5, repeat: Infinity }}
                    className="absolute inset-0 z-0 pointer-events-none opacity-50"
                />

                <motion.div 
                    className="relative z-10 bg-black border-4 border-red-600 p-8 md:p-12 rounded-lg max-w-2xl w-full text-center shadow-[0_0_50px_rgba(220,38,38,0.5)]"
                    initial={{ scale: 0.9 }}
                    animate={{ scale: [1, 1.02, 1] }}
                    transition={{ repeat: Infinity, duration: 0.2 }}
                >
                    <div className="mb-4">
                         <span className="text-6xl">🚨</span>
                    </div>
                    <h1 className="text-4xl md:text-6xl font-black text-red-500 mb-2 tracking-tighter" style={{ textShadow: '0 0 10px red' }}>
                        NOT ELIGIBLE
                    </h1>
                    <div className="text-3xl font-bold mb-6 text-red-200 font-mono">{percentage.toFixed(1)}%</div>

                    <p className="text-xl md:text-2xl text-white font-bold mb-8 uppercase font-mono leading-tight bg-red-900/30 p-4 rounded border border-red-500/30">
                        {roast}
                    </p>

                    <div className="space-y-4">
                        <button 
                            onClick={handleMedicalCertificate}
                            disabled={medicalStatus !== 'idle'}
                            className="bg-yellow-600 hover:bg-yellow-500 text-black font-bold py-4 px-8 rounded uppercase tracking-wider text-sm md:text-base w-full md:w-auto transition-all shadow-lg hover:shadow-yellow-500/50"
                        >
                            {medicalStatus === 'idle' && "Try with Medical Certificate"}
                            {medicalStatus === 'checking' && "Verifying Certificate..."}
                            {medicalStatus === 'rejected' && "❌ REJECTED"}
                        </button>

                        {medicalStatus === 'rejected' && (
                            <motion.div 
                                initial={{ opacity: 0, height: 0 }}
                                animate={{ opacity: 1, height: 'auto' }}
                                className="bg-red-900/50 p-2 rounded border border-red-500 text-red-200 font-mono text-sm"
                            >
                                SYSTEM REASON: {medicalRejectReason}
                            </motion.div>
                        )}
                    </div>
                </motion.div>

                {/* Fake Call Overlay */}
                <AnimatePresence>
                    {showFakeCall && (
                        <motion.div
                            initial={{ y: '100%' }}
                            animate={{ y: 0 }}
                            exit={{ y: '100%' }}
                            className="absolute bottom-0 left-0 right-0 bg-gray-900 border-t border-gray-700 p-6 z-50 flex items-center justify-between shadow-2xl"
                        >
                            {callStatus === 'incoming' ? (
                                <>
                                    <div className="flex items-center gap-4">
                                        <div className="w-14 h-14 bg-gray-700 rounded-full flex items-center justify-center text-2xl animate-pulse ring-4 ring-gray-600">
                                            📞
                                        </div>
                                        <div>
                                            <h4 className="text-white font-bold text-xl">HOD Calling...</h4>
                                            <p className="text-gray-400 text-sm">Mobile • +91 98XXX XXXXX</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-6">
                                        <button onClick={() => setShowFakeCall(false)} className="flex flex-col items-center gap-1 group">
                                             <div className="w-14 h-14 rounded-full bg-red-500 flex items-center justify-center shadow-lg group-hover:bg-red-600 transition-colors">
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                                </svg>
                                             </div>
                                             <span className="text-xs text-gray-400">Decline</span>
                                        </button>
                                        <button onClick={answerCall} className="flex flex-col items-center gap-1 group">
                                            <div className="w-14 h-14 rounded-full bg-green-500 flex items-center justify-center animate-bounce shadow-lg group-hover:bg-green-600 transition-colors">
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
                                                </svg>
                                            </div>
                                            <span className="text-xs text-gray-400">Answer</span>
                                        </button>
                                    </div>
                                </>
                            ) : (
                                <div className="w-full flex items-center justify-center py-4">
                                     <div className="text-center space-y-2">
                                        <h4 className="text-green-400 font-bold text-xl tracking-wide">CONNECTED 00:01</h4>
                                        <p className="text-white text-2xl font-black uppercase animate-pulse">
                                            "PLEASE MEET AFTER CLASS"
                                        </p>
                                     </div>
                                </div>
                            )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
         )}
       </motion.div>
    </AnimatePresence>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface TrollGameProps {
  isOpen: boolean;
  onClose: () => void;
}

const ROASTS = [
  "Teacher forgot your face",
  "Security thinks you’re a visitor",
  "Even WiFi attends more than you",
  "Bring parents tomorrow",
  "Attendance found in museum records",
  "You attend only on result day?",
  "HOD asks 'Who is this?'",
  "Your seat has been sold to a junior"
];

const LOADING_MSGS = [
  "Verifying with university server...",
  "Contacting HOD...",
  "Checking CCTV footage...",
  "Calculating bunk velocity...",
  "Analyzing excuses database..."
];

export const TrollGame: React.FC<TrollGameProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<'form' | 'loading' | 'result'>('form');
  const [name, setName] = useState('');
  const [total, setTotal] = useState('');
  const [attended, setAttended] = useState('');
  const [examDate, setExamDate] = useState('');
  const [holidays, setHolidays] = useState(''); 
  const [loadingIndex, setLoadingIndex] = useState(0);
  const [isEligible, setIsEligible] = useState(false);
  const [percentage, setPercentage] = useState(0);
  const [roast, setRoast] = useState('');
  const [showFakeCall, setShowFakeCall] = useState(false);
  const [callStatus, setCallStatus] = useState<'incoming' | 'connected'>('incoming');
  const [medicalStatus, setMedicalStatus] = useState<'idle' | 'checking' | 'rejected'>('idle');
  const [medicalRejectReason, setMedicalRejectReason] = useState('');
  const [thunderFlash, setThunderFlash] = useState(false);

  // Audio Refs
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeOscillatorsRef = useRef<OscillatorNode[]>([]);
  const ringtoneIntervalRef = useRef<number | null>(null);

  const initAudio = () => {
    if (!audioCtxRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContextClass) {
          audioCtxRef.current = new AudioContextClass();
      }
    }
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }
  };

  const stopAllSounds = () => {
    activeOscillatorsRef.current.forEach(osc => {
        try { osc.stop(); osc.disconnect(); } catch(e) {}
    });
    activeOscillatorsRef.current = [];
    if (ringtoneIntervalRef.current) {
        clearInterval(ringtoneIntervalRef.current);
        ringtoneIntervalRef.current = null;
    }
  };

  const playAnimeThunder = () => {
    stopAllSounds();
    initAudio();
    const ctx = audioCtxRef.current;
    if(!ctx) return;

    // Low frequency rumble
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(40, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(10, ctx.currentTime + 3);
    gain.gain.setValueAtTime(0.3, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 3);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();

    // High frequency crack
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = 'square';
    osc2.frequency.setValueAtTime(100, ctx.currentTime);
    gain2.gain.setValueAtTime(0.2, ctx.currentTime);
    gain2.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
    osc2.connect(gain2);
    gain2.connect(ctx.destination);
    osc2.start();
  };

  const playAnimeSuccess = () => {
    stopAllSounds();
    initAudio();
    const ctx = audioCtxRef.current;
    if(!ctx) return;

    const now = ctx.currentTime;
    const notes = [440, 554, 659, 880]; // A4, C#5, E5, A5
    notes.forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, now + i * 0.1);
        gain.gain.setValueAtTime(0, now + i * 0.1);
        gain.gain.linearRampToValueAtTime(0.1, now + i * 0.1 + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, now + i * 0.1 + 1);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + i * 0.1);
        osc.stop(now + 2);
    });
  };

  const playRingtone = () => {
    stopAllSounds();
    initAudio();
    const ctx = audioCtxRef.current;
    if(!ctx) return;
    const playRing = () => {
        const now = ctx.currentTime;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'square';
        osc.frequency.value = 800;
        gain.gain.setValueAtTime(0.05, now);
        gain.gain.linearRampToValueAtTime(0, now + 1.0);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now);
        osc.stop(now + 1.0);
        activeOscillatorsRef.current.push(osc);
    };
    playRing();
    ringtoneIntervalRef.current = window.setInterval(playRing, 2000);
  };

  const playErrorBuzz = () => {
      initAudio();
      const ctx = audioCtxRef.current;
      if(!ctx) return;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, ctx.currentTime);
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.4);
  };

  useEffect(() => {
    if (isOpen) {
      setStep('form');
      setMedicalStatus('idle');
      setShowFakeCall(false);
      setCallStatus('incoming');
      setName('');
      setTotal('');
      setAttended('');
      setExamDate('');
      setHolidays('');
      stopAllSounds();
    } else {
      stopAllSounds();
    }
    return () => stopAllSounds();
  }, [isOpen]);

  useEffect(() => {
    if (step === 'loading') {
      const interval = setInterval(() => {
        setLoadingIndex(prev => (prev + 1) % LOADING_MSGS.length);
      }, 800);

      const timeout = setTimeout(() => {
        clearInterval(interval);
        const t = parseInt(total) || 0;
        const a = parseInt(attended) || 0;
        const pct = t === 0 ? 0 : (a / t) * 100;
        setPercentage(pct);

        const eligible = pct >= 75;
        setIsEligible(eligible);

        if (eligible) {
            playAnimeSuccess();
        } else {
            playAnimeThunder();
            setRoast(ROASTS[Math.floor(Math.random() * ROASTS.length)]);
            setTimeout(() => {
                setShowFakeCall(true);
                playRingtone();
            }, 5000);
        }
        setStep('result');
      }, 3500);

      return () => {
        clearInterval(interval);
        clearTimeout(timeout);
      }
    }
  }, [step, total, attended]);

  // Lightning effect for fail scene
  useEffect(() => {
    if (step === 'result' && !isEligible) {
        const triggerFlash = () => {
            setThunderFlash(true);
            setTimeout(() => setThunderFlash(false), 100);
            if (Math.random() > 0.5) {
                setTimeout(() => {
                    setThunderFlash(true);
                    setTimeout(() => setThunderFlash(false), 50);
                }, 150);
            }
        };
        const interval = setInterval(() => {
            if (Math.random() > 0.7) triggerFlash();
        }, 3000);
        return () => clearInterval(interval);
    }
  }, [step, isEligible]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    initAudio();
    if (!total || !attended) return;
    setStep('loading');
  };

  const handleMedicalCertificate = () => {
    initAudio();
    setMedicalStatus('checking');
    setTimeout(() => {
        const reasons = ["Ink too fresh", "Doctor is your uncle", "HOD denied instantly", "Certificate used by 5 others"];
        setMedicalRejectReason(reasons[Math.floor(Math.random() * reasons.length)]);
        setMedicalStatus('rejected');
        playErrorBuzz();
    }, 1500);
  };

  const answerCall = () => {
    initAudio();
    setCallStatus('connected');
    stopAllSounds();
    setTimeout(() => {
        setShowFakeCall(false);
        setCallStatus('incoming');
    }, 4000);
  };

  const handleClose = () => {
    stopAllSounds();
    onClose();
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
       <motion.div 
         initial={{ opacity: 0 }} 
         animate={{ opacity: 1 }} 
         exit={{ opacity: 0 }}
         className="fixed inset-0 z-[100000] bg-black/95 flex items-center justify-center font-sans overflow-hidden"
       >
         <button onClick={handleClose} className="absolute top-4 right-4 text-white/50 hover:text-white z-[100001] bg-black/20 p-2 rounded-full backdrop-blur-md">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
         </button>

         {step === 'form' && (
            <motion.div 
                initial={{ scale: 0.9, y: 20 }}
                animate={{ scale: 1, y: 0 }}
                className="bg-white rounded-lg shadow-2xl w-full max-w-md overflow-hidden relative z-50 mx-4"
            >
                <div className="bg-blue-900 p-6 text-center border-b-4 border-yellow-500">
                    <h2 className="text-2xl font-bold text-white uppercase tracking-wider">University Portal</h2>
                    <p className="text-blue-200 text-xs mt-1 font-mono">Exam Dept. Eligibility Verification</p>
                </div>
                <form onSubmit={handleSubmit} className="p-8 space-y-4">
                    <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Student Name</label>
                        <input required type="text" className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black transition-colors" placeholder="Full name as per ID" value={name} onChange={e => setName(e.target.value)} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Total Classes</label>
                            <input required type="number" className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black" value={total} onChange={e => setTotal(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Attended</label>
                            <input required type="number" className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black" value={attended} onChange={e => setAttended(e.target.value)} />
                        </div>
                    </div>
                    <div>
                        <label className="block text-gray-700 text-xs font-bold mb-1 uppercase tracking-wide">Exam Start Date</label>
                        <input type="date" className="w-full border-2 border-gray-300 p-3 rounded bg-gray-50 focus:outline-none focus:border-blue-800 text-black" value={examDate} onChange={e => setExamDate(e.target.value)} />
                    </div>
                    <button type="submit" className="w-full bg-blue-800 hover:bg-blue-900 text-white font-bold py-4 rounded shadow-lg transform transition active:scale-95 flex justify-center items-center gap-2 mt-4">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        GENERATE ELIGIBILITY
                    </button>
                    <p className="text-[10px] text-center text-gray-400 uppercase mt-2">Authenticated Session • Encrypted Portal</p>
                </form>
            </motion.div>
         )}

         {step === 'loading' && (
            <div className="text-center text-white space-y-8 z-50">
                <div className="relative">
                    <div className="w-24 h-24 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
                    <div className="absolute inset-0 flex items-center justify-center"><span className="text-2xl">⚡</span></div>
                </div>
                <div className="space-y-2">
                    <h3 className="text-2xl font-bold font-mono tracking-widest text-blue-400">ANALYZING RECORDS...</h3>
                    <motion.p key={loadingIndex} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="text-blue-200 font-mono text-sm">{LOADING_MSGS[loadingIndex]}</motion.p>
                </div>
            </div>
         )}

         {step === 'result' && isEligible && (
            <div className="absolute inset-0 flex items-center justify-center bg-blue-400 overflow-hidden">
                {/* Anime Background - Blue Sky & Clouds */}
                <div className="absolute inset-0 bg-gradient-to-b from-blue-300 to-white">
                    <motion.div animate={{ x: [-100, 1000] }} transition={{ duration: 40, repeat: Infinity, ease: 'linear' }} className="absolute top-20 left-0 text-9xl opacity-30 select-none">☁️</motion.div>
                    <motion.div animate={{ x: [1200, -200] }} transition={{ duration: 30, repeat: Infinity, ease: 'linear' }} className="absolute top-60 right-0 text-9xl opacity-20 select-none">☁️</motion.div>
                    <div className="absolute bottom-0 w-full h-1/4 bg-green-500/20" />
                </div>

                {/* Wind lines */}
                <div className="absolute inset-0 pointer-events-none">
                    {[...Array(10)].map((_, i) => (
                        <motion.div key={i} animate={{ x: [-200, 1200], opacity: [0, 1, 0] }} transition={{ duration: 0.8, repeat: Infinity, delay: i * 0.3 }} className="absolute h-px bg-white/40" style={{ top: `${10 + i * 8}%`, width: '150px' }} />
                    ))}
                </div>

                {/* Hero Walking Animation (Simplified silhouette) */}
                <div className="relative z-10 text-center space-y-8">
                    <motion.div initial={{ y: 300, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ type: 'spring', duration: 1 }} className="mb-20">
                         {/* Student Silhouette */}
                         <div className="w-40 h-64 mx-auto relative group">
                            <motion.div animate={{ y: [0, -5, 0] }} transition={{ repeat: Infinity, duration: 0.4 }} className="w-16 h-16 bg-black rounded-full mx-auto" />
                            <motion.div animate={{ rotate: [-2, 2, -2] }} transition={{ repeat: Infinity, duration: 0.4 }} className="w-24 h-40 bg-black rounded-3xl mx-auto -mt-2 relative">
                                {/* Backpack */}
                                <div className="absolute top-4 -right-4 w-12 h-24 bg-gray-900 rounded-lg" />
                            </motion.div>
                            <div className="flex justify-center gap-4 -mt-4">
                                <motion.div animate={{ rotate: [10, -20, 10] }} transition={{ repeat: Infinity, duration: 0.4 }} className="w-6 h-20 bg-black rounded-full origin-top" />
                                <motion.div animate={{ rotate: [-20, 10, -20] }} transition={{ repeat: Infinity, duration: 0.4 }} className="w-6 h-20 bg-black rounded-full origin-top" />
                            </div>
                         </div>
                    </motion.div>

                    <div className="space-y-2">
                         <motion.div initial={{ scale: 2, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: 1, duration: 0.5 }} className="text-6xl md:text-8xl font-black text-blue-900 tracking-tighter drop-shadow-2xl italic">ELIGIBLE</motion.div>
                         <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 1.5 }} className="text-2xl text-blue-800 font-bold uppercase tracking-widest bg-white/40 backdrop-blur-sm px-6 py-2 rounded-full inline-block">“You trained hard… you are ready.”</motion.p>
                    </div>

                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 2.5 }} className="pt-10">
                        <div className="text-4xl font-black text-white bg-green-500 px-8 py-4 rounded-xl shadow-2xl rotate-3 inline-block">
                            SCORE: {percentage.toFixed(1)}%
                        </div>
                    </motion.div>
                </div>
            </div>
         )}

         {step === 'result' && !isEligible && (
            <div className="absolute inset-0 flex items-center justify-center bg-black overflow-hidden">
                {/* Lightning Flash Layer */}
                <AnimatePresence>
                    {thunderFlash && (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-white z-[1]" />
                    )}
                </AnimatePresence>

                {/* Anime Background - Dark Stormy Sky */}
                <div className="absolute inset-0 bg-gradient-to-t from-black via-purple-950 to-indigo-950">
                    <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_50%_50%,rgba(0,0,0,0)_0%,rgba(0,0,0,1)_100%)]" />
                    {[...Array(20)].map((_, i) => (
                        <motion.div key={i} animate={{ opacity: [0.1, 0.3, 0.1], scale: [1, 1.1, 1] }} transition={{ duration: 3 + i, repeat: Infinity }} className="absolute bg-black/40 blur-3xl rounded-full" style={{ width: '400px', height: '200px', top: `${Math.random() * 100}%`, left: `${Math.random() * 100}%` }} />
                    ))}
                </div>

                {/* Rain Effect */}
                <div className="absolute inset-0 pointer-events-none opacity-30">
                    {[...Array(50)].map((_, i) => (
                        <motion.div key={i} animate={{ y: [0, 1000] }} transition={{ duration: 0.5, repeat: Infinity, delay: Math.random() }} className="absolute w-[1px] h-20 bg-blue-300" style={{ left: `${Math.random() * 100}%`, top: '-100px' }} />
                    ))}
                </div>

                <div className="relative z-10 text-center w-full max-w-4xl px-4">
                    {/* Teacher Silhouette */}
                    <motion.div initial={{ scale: 0.5, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ duration: 1.5, ease: 'easeOut' }} className="mb-10 relative">
                        <div className="w-64 h-80 mx-auto relative">
                             {/* Scary silhouette */}
                             <motion.div animate={{ scale: [1, 1.05, 1] }} transition={{ repeat: Infinity, duration: 2 }} className="absolute inset-0 flex flex-col items-center">
                                <div className="w-24 h-24 bg-black rounded-full shadow-[0_0_30px_rgba(168,85,247,0.4)]" />
                                <div className="w-48 h-64 bg-black rounded-t-[100px] -mt-2 flex items-start justify-center pt-8">
                                     <div className="flex gap-10">
                                        <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse shadow-[0_0_10px_red]" />
                                        <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse shadow-[0_0_10px_red]" />
                                     </div>
                                </div>
                             </motion.div>
                        </div>
                        {/* Dramatic Red Text Backdrop */}
                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                            <motion.div initial={{ scale: 5, opacity: 0 }} animate={{ scale: 1, opacity: 0.2 }} transition={{ delay: 0.5 }} className="text-[200px] font-black text-red-600 italic select-none">FAILED</motion.div>
                        </div>
                    </motion.div>

                    <div className="space-y-8">
                        <motion.h2 initial={{ opacity: 0, x: -100 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 1, duration: 0.8 }} className="text-5xl md:text-8xl font-black text-red-600 italic tracking-tighter uppercase drop-shadow-[0_0_20px_rgba(220,38,38,0.8)]">
                            NOT ELIGIBLE
                        </motion.h2>

                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 2 }} className="space-y-4">
                            <p className="text-2xl md:text-3xl text-white font-mono font-bold tracking-widest bg-red-950/80 px-8 py-4 rounded-lg border border-red-500 inline-block">
                                “{roast}”
                            </p>
                            <p className="text-red-400 font-mono text-sm uppercase tracking-[0.4em]">Current Rate: {percentage.toFixed(1)}% / 75.0%</p>
                        </motion.div>

                        <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 3 }} className="pt-6">
                            <button onClick={handleMedicalCertificate} disabled={medicalStatus !== 'idle'} className="bg-yellow-600 hover:bg-yellow-500 text-black font-black py-4 px-10 rounded uppercase tracking-widest shadow-[0_0_30px_rgba(202,138,4,0.3)] transition-all">
                                {medicalStatus === 'idle' ? "SUBMIT MEDICAL CERTIFICATE" : medicalStatus === 'checking' ? "VERIFYING DOCS..." : "SYSTEM DENIED"}
                            </button>
                            {medicalStatus === 'rejected' && (
                                <motion.p animate={{ x: [-2, 2, -2] }} transition={{ repeat: Infinity, duration: 0.1 }} className="text-red-500 font-mono mt-4 font-bold uppercase tracking-wider">
                                    ERROR: {medicalRejectReason}
                                </motion.p>
                            )}
                        </motion.div>
                    </div>
                </div>

                {/* Fake Call Popup */}
                <AnimatePresence>
                    {showFakeCall && (
                        <motion.div initial={{ y: 300 }} animate={{ y: 0 }} exit={{ y: 300 }} className="absolute bottom-10 left-4 right-4 md:left-auto md:right-10 md:w-96 bg-gray-900 border-2 border-red-600 rounded-3xl p-6 z-[100] shadow-[0_0_50px_rgba(220,38,38,0.4)]">
                             {callStatus === 'incoming' ? (
                                <div className="flex flex-col items-center gap-6">
                                    <div className="flex items-center gap-4 w-full">
                                        <div className="w-16 h-16 bg-red-600 rounded-full flex items-center justify-center text-3xl animate-bounce shadow-lg">📞</div>
                                        <div className="text-left">
                                            <h4 className="text-white font-black text-2xl tracking-tighter">HOD CALLING</h4>
                                            <p className="text-red-400 font-mono text-xs uppercase animate-pulse">Critical: Zero Attendance Detected</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-4 w-full">
                                        <button onClick={() => setShowFakeCall(false)} className="flex-1 bg-gray-800 text-white font-bold py-4 rounded-2xl hover:bg-gray-700">DECLINE</button>
                                        <button onClick={answerCall} className="flex-1 bg-green-600 text-white font-bold py-4 rounded-2xl animate-pulse">ANSWER</button>
                                    </div>
                                </div>
                             ) : (
                                <div className="text-center py-4 space-y-4">
                                     <div className="text-green-500 font-mono text-sm tracking-widest">CONNECTED • 00:0{Math.floor(Math.random()*9)}</div>
                                     <h3 className="text-white text-3xl font-black italic tracking-tighter uppercase">“PLEASE MEET AFTER CLASS”</h3>
                                     <div className="w-full h-1 bg-gray-800 rounded-full overflow-hidden"><motion.div animate={{ x: [-200, 400] }} transition={{ duration: 1, repeat: Infinity }} className="w-20 h-full bg-green-500" /></div>
                                </div>
                             )}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
         )}
       </motion.div>
    </AnimatePresence>
  );
}
